import{H as e,V as t,et as n,j as r}from"./chunks/framework.DKIRGhFK.js";import{Of as i,kf as a}from"./chunks/assets.CUKu7Ix7.js";var o=JSON.parse(`{"title":"Maven常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"java/maven/common-issues.md","filePath":"java/maven/common-issues.md"}`),s={name:`java/maven/common-issues.md`};function c(r,o,s,c,l,u){return n(),t(`div`,null,[...o[0]||=[e(`<h1 id="maven常见问题" tabindex="-1">Maven常见问题 <a class="header-anchor" href="#maven常见问题" aria-label="Permalink to “Maven常见问题”">​</a></h1><p><img src="`+a+`" alt="image.png" width="1914" height="747"></p><ul><li><p><strong>问题现象：</strong>Maven项目中添加的依赖，未正确下载，造成右侧Maven面板中的依赖报红，再次reload重新加载也不会再下载。</p></li><li><p><strong>产生原因：</strong>由于网络原因，依赖没有下载完整导致的，在maven仓库中生成了<strong>xxx.lastUpdated</strong>文件，该文件不删除，不会再重新下载。</p></li></ul><p><img src="`+i+`" alt="image.png" width="1240" height="421"></p><p><strong>解决方案：</strong></p><ol><li><p>根据maven依赖的坐标，找到仓库中对应的 xxx.lastUpdated 文件，删除，删除之后重新加载项目即可。</p></li><li><p>通过命令 (del /s *.lastUpdated) 批量递归删除指定目录下的 xxx.lastUpdated 文件，删除之后重新加载项目即可。</p></li><li><p>重新加载依赖，依赖下载了之后，maven面板可能还会报红，此时可以关闭IDEA，重新打开IDEA加载此项目即可。</p></li></ol>`,6)]])}var l=r(s,[[`render`,c]]);export{o as __pageData,l as default};